data.query:
query Query($P: ProductWhereInput, $C: ProductWhereInput) {
  assembly: product(where: $P) {
    edges {
      node {
        id
        active
        externalId
        name
        integrationData
        productTypeId
        strategies(where: {_not: {strategyTypeId: {_in: ["Inventory", "By Product"]}}, active: {_eq: true}}) {
          total
          edges {
            node {
              id
              facilityId
              facility {
                id
                externalId
              }
              active
              primary
              validated
              externalId
              effectiveAt
              expirationAt
              integrationData
              strategyTypeId
              strategyProcesses {
                edges {
                  node {
                    id
                    processId
                    assemblyBoms {
                      edges {
                        node {
                          id
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  component: product(where: $C) {
    edges {
      node {
        id
        productTypeId
        externalId
        strategies(where: {_or: [{primary: {_eq: true}, strategyType: {assembly: {_eq: true}}}, {strategyType: {inventory: {_eq: true}}}],active:{_eq:true}}) {
          edges {
            node {
              id
              facility {
                id
                code
              }
              strategyTypeId
              strategyProcesses(where: {final: {_eq: true}}, first: 1) {
                edges {
                  node {
                    id
                    processId
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  facility(where: {active: {_eq: true}}) {
    edges {
      node {
        id
        code
        externalId
        name
      }
    }
  }
}

