function splitData(input) {
  let result = [];

  input.forEach(item => {
    let locations = item.r_location.split(',');
    locations.forEach(location => {
      let newItem = { ...item, r_location: location.trim(), revId: item.r_id + "-" + location.trim() + "-" + item.r_billofmaterials };
      result.push(newItem);
    });
  });

  return result;
}

