      node {
        id
        externalId
      }
    }
  }
  unit(where: $unit) {
    edges {
      node {
        id
      }
    }
  }
  location(where: $location) {
    edges {
      node {
        id
        name
        facility {
          externalId
        }
      }
    }
  }
  facility(where: $facility) {
    edges {
      node {
        id
        externalId
      }
    }
  }
  receipt(where: $receipt) {
    edges {
      node {
        id
        number
        externalId
        statusId
        lines {
          edges {
            node {
              id
              number
              externalId
              statusId
              inventories {
                edges {
                  node {
                    id
                    customData
                    inventoryStatusId
                    externalId
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

