		$receipt := $state.context.LOCAL.receipt;
		$masterInventoryStatusId := $predicateFilter($state.context.LOCAL.masterInventoryStatuses,{
				"active": { "_eq": true },
				"containment": { "_eq": false },
				"empty": { "_eq": false },
				"loaded": { "_eq": false },
				"mergePrevent": { "_eq": false },
