				"picked": { "_eq": false },
				"productionLoaded": { "_eq": false },
				"productionPrevent": { "_eq": false },
				"received": { "_eq": false },
				"shipPrevent": { "_eq": false },
				"shipped": { "_eq": false },
				"splitPrevent": { "_eq": false },
				"staged": { "_eq": false },
				"usable": { "_eq": true }
			},{ "caseSensitiveComparison": false })[0].id;
		/* current seed data setup prevents proper lookup */
		$inventoryStatusId := $predicateFilter(
			$state.context.LOCAL.inventoryStatuses,
			{
				"active": { "_eq": true },
				"containment": { "_eq": false },
				"defective": { "_eq": false },
				"loaded": { "_eq": false },
				"mergePrevent": { "_eq": false },
				"movePrevent": { "_eq": false },
				"picked": { "_eq": false },
				"productionLoaded": { "_eq": false },
				"productionPrevent": { "_eq": false },
				"received": { "_eq": false },
				"shipPrevent": { "_eq": false },
				"shipped": { "_eq": false },
				"splitPrevent": { "_eq": false },
				"staged": { "_eq": false },
				"suspect": { "_eq": false }
			},{ "caseSensitiveComparison": false })[0].id;
		$confirmedReceiptStatus := $predicateFilter($state.context.LOCAL.receiptStatuses,{"active": { "_eq": false },"confirmed": { "_eq": true }
},{ "caseSensitiveComparison": false })[0].id;
		{
			/* updateReceiptPayload */
			"payload": $
				.{
					"update": {
						"statusId": $confirmedReceiptStatus,
						"externalId": $string(trx.recordId)
					},
					"where": { "id": receipt.id }
				},
			/* updateReceiptLine payload */
			"payloadL": $receipt
				.lines
				.edges
				.node
				.{
					"update": { "statusId": $confirmedReceiptStatus },
					"where": { "id": id }
				},
			/* Update Linked Inventory that was previously shipped and now returned under new serial number */
			"payloadInventoryReturn": [
				$state
					.context
					.LOCAL
					.receipt
					.lines
					.edges
					.node
					.inventories
					.edges
					.node
					.customData
					.inventoryRMA
					.{
						"update": {
							"inventoryStatusId": "Returned",
							"active": false
						},
						"where": { "id": $ }
					}
			],
			/* updateInventory payload */
			"payloadI": [
				$state.context.LOCAL.receipt.lines.edges.node.inventories.edges.node.{
						"update": {
							"inventoryStatusId": "Returned",
							/* seed data requires review $inventoryStatusId */
							"active": true
						},
						"where": { "id": id }
					}
			],
			/* updateMasterInventory payload */
			"payloadMasterInventory": [
				$uniqBy(
					$state
						.context
						.LOCAL
						.receipt
						.lines
						.edges
						.node
						.inventories
						.edges
						.node,
					function($v) { $v.masterInventoryId }
				)
					.{
						"update": {
							"masterInventoryStatusId": $masterInventoryStatusId,
							"active": true
						},
						"where": { "id": masterInventoryId }
					}
			],
      /* Create Inventory Transaction */
      "payloadInventoryTransaction": [$state.context.LOCAL.receipt.lines.edges.node.inventories.edges.node[$exists(customData.inventoryRMA)].{
        "create": {
          "destinationInventoryId": id,
          "destinationInventoryStatusId": inventoryStatusId,
          "destinationLocationId": locationId,
          "destinationQuantity":  quantity.{ "value":value , "unitId": unitId},
          "sourceInventoryId": customData.inventoryRMA,
          "sourceInventoryStatusId": "Pending Return",
          "sourceLocationId": customData.locationId,
