(
  /*
    If the master has inventory with multiple different parts this master can only be loaded to a shipment that has
    lines for each part. If the lines span more then one shipment we must reject the master. A single master can only go
    to one shipment.
  */

  $arrayContainsArray := function($a1, $a2){
    $all($a1, function($v){ $v in $a2})
  };

  $groupedLines := shipmentLine.edges.node{`shipmentId`: $};
  $masterProducts := $uniq(master.edges.node.inventory.edges.node.productId);

  $doShipmentsHaveAllPartsOnMaster := $mapValues($groupedLines, function($v){(
    $arrayContainsArray($masterProducts, $v.productId)
  )})~>$values;

  $not(true in $doShipmentsHaveAllPartsOnMaster)

)

